["RAIDBOSS_CNY24"]="SON OF THE SUN",
["RAIDBOSS_CNY24_Title"]="Son of the Sun",
["HigherChanceLable"]="Higher Chance",
["dlgCNY24_Story_Sun1"]="Here I stand before you, bask in my dazzling rays of greatness! Behold as my luminary fury descends upon you! Accept my challenge!",
["HELM_CNY2024_MASK"]="Daybreak's Visage",
["Potion_resistance_hint_full"]="Most effective against bosses starting from the 2nd tier of the Underworld.",
